"use strict";(function($){if("loading"in HTMLImageElement.prototype){$("img.lazyload").each(function(){this.src=this.dataset.src})}else{const script=document.createElement("script");script.async=true;script.src="https://cdnjs.cloudflare.com/ajax/libs/lazysizes/5.2.0/lazysizes.min.js";document.body.appendChild(script)}$(document).ready(function(){const search=$("#search-model"),input=$('input[name="q"]');$(".search-button").on("click",function(){search.fadeIn(400);input.focus()});search.find(".close").on("click",function(){search.fadeOut(400,function(){$("#search-input").val("")})})})})(jQuery);